# ──────────────────────────────────────────────────────────────────────────────
# Streaming Chat (blocking SSE consumption with placeholder updates)
#
# The chat answer is generated by a backend background job and consumed via SSE.
# The script run blocks on the SSE stream and updates st.empty() placeholders as
# status / reasoning / answer events arrive. The placeholders are created INSIDE
# the message area (via progress_ph) BEFORE the chat input, so chat-element
# ordering stays correct and the answer renders in place with live progress —
# no refresh needed. Streamlit 1.62 has no script-run timeout.
# ──────────────────────────────────────────────────────────────────────────────


def _blocking_stream(job_id: str, status_ph, thinking_ph, msg_ph):
    """
    Blocks on the SSE chat stream and renders progress into placeholders.

    Returns (answer_text, result_event_dict).
    """
    answer = ""
    thinking = ""
    with api_client.stream("GET", f"/api/v1/chat/stream/{job_id}") as resp:
        for line in resp.iter_lines():
            if not line or not line.startswith("data: "):
                continue
            try:
                evt = json.loads(line[6:])
            except Exception:
                continue
            etype = evt.get("type")
            if etype == "token":
                answer += evt.get("text", "")
                if msg_ph is not None:
                    msg_ph.markdown(answer)
            elif etype == "thinking":
                thinking += evt.get("text", "")
                preview = thinking[-400:]
                if thinking_ph is not None:
                    thinking_ph.markdown(
                        f"<div style='color:#94a3b8;font-size:0.85em;white-space:pre-wrap;'>Reasoning: {preview}</div>",
                        unsafe_allow_html=True,
                    )
            elif etype == "status":
                msg = evt.get("message", "")
                if msg and status_ph is not None:
                    status_ph.markdown(
                        f"<div style='color:#3b82f6;font-size:0.85em;margin-bottom:6px;font-weight:500;'>{msg}</div>",
                        unsafe_allow_html=True,
                    )
            elif etype == "done":
                if status_ph is not None:
                    status_ph.empty()
                if thinking_ph is not None:
                    thinking_ph.empty()
                return answer, evt
            elif etype == "error":
                if status_ph is not None:
                    status_ph.empty()
                if thinking_ph is not None:
                    thinking_ph.empty()
                if msg_ph is not None:
                    msg_ph.markdown(evt.get("message", "Chat failed."))
                return answer, {"type": "done", "answer": evt.get("message", "")}
    return answer, {"type": "done", "answer": answer or "No response received."}

