# ──────────────────────────────────────────────────────────────────────────────
# CHAT SESSION SIDEBAR (multi-session history access)
# ──────────────────────────────────────────────────────────────────────────────
def _fetch_sessions():
    try:
        resp = api_client.get("/api/v1/chat/sessions")
        if resp.status_code == 200:
            return resp.json()
    except Exception:
        pass
    return []


def _create_new_session():
    try:
        resp = api_client.post("/api/v1/chat/sessions")
        if resp.status_code == 200:
            return resp.json().get("id")
    except Exception:
        pass
    return None


def _render_session_panel():
    """Renders the chat-session panel inside a single outer card box with internal scrolling."""
    with st.container(border=True):
        st.markdown(
            """
            <div style="font-family: 'Outfit', sans-serif; font-size: 0.8rem; font-weight: 700; color: #64748b; letter-spacing: 1px; margin-bottom: 10px; text-transform: uppercase;">
                CHAT SESSIONS
            </div>
            """,
            unsafe_allow_html=True,
        )

        if st.button("+ New Chat", key="new_chat_btn", use_container_width=True, type="primary"):
            new_id = _create_new_session()
            if new_id:
                st.session_state.current_session_id = new_id
                st.session_state.show_wrapper = True
                st.rerun()

        sessions = _fetch_sessions()
        st.session_state.chat_sessions = sessions

        st.markdown("<div style='height: 8px;'></div>", unsafe_allow_html=True)

        if not sessions:
            st.caption("No sessions yet. Start a new chat.")
            return

        # Fixed-height scrollable container matching chat window height
        with st.container(height=CHAT_MESSAGES_HEIGHT, border=False):
            for s in sessions:
                sid = s["id"]
                title = s["title"] or "New chat"
                is_active = sid == st.session_state.current_session_id
                if s.get("frozen"):
                    title = f"{title}  [full]"
                row = st.columns([5, 1])
                with row[0]:
                    if is_active:
                        st.markdown(
                            f'<div class="sess-item sess-item-active">{title}</div>',
                            unsafe_allow_html=True,
                        )
                    else:
                        if st.button(title, key=f"sess_btn_{sid}", use_container_width=True):
                            st.session_state.current_session_id = sid
                            st.session_state.show_wrapper = True
                            st.rerun()
                with row[1]:
                    if st.button("x", key=f"sess_del_{sid}", help="Delete session", use_container_width=True):
                        try:
                            api_client.delete(f"/api/v1/chat/sessions/{sid}")
                        except Exception:
                            pass
                        if st.session_state.current_session_id == sid:
                            st.session_state.current_session_id = None
                            st.session_state.show_wrapper = False
                        st.rerun()


def _render_chat_window(
    session_id,
    server_messages,
    optimistic,
    session_title,
    session_frozen,
    usage_tokens,
    context_threshold,
    pending_query=None,
):
    """Renders the Gemini-style chat window. Returns the active query if any turn was submitted."""
    with st.container(border=True):
        st.markdown(
            f"""
            <div class="chat-window-header">
                <span class="chat-window-title">{session_title}</span>
                {("<span class='chat-window-full'>context full</span>" if session_frozen else "")}
            </div>
            """,
            unsafe_allow_html=True,
        )

        if session_frozen:
            st.warning("Context window full, open a new session.")

        # Fixed-height, internally scrollable message area (never grows the card).
        with st.container(height=CHAT_MESSAGES_HEIGHT, border=False):
            st.markdown('<div class="chat-scroll-marker"></div>', unsafe_allow_html=True)
            for msg in server_messages + optimistic:
                with st.chat_message(msg["role"]):
                    st.markdown(msg["content"])
            progress_ph = st.empty()

        # Inline typing box (always visible; disabled while a turn is in progress).
        conv_query = st.chat_input(
            "Ask anything",
            disabled=session_frozen or bool(optimistic),
            key="chat_input_conv",
        )

        status_ph = thinking_ph = stream_ph = None
        if conv_query:
            optimistic.append({"role": "user", "content": conv_query})
            st.session_state.optimistic_messages = optimistic
            active_query = conv_query
            # Render the current turn into progress_ph (positioned inside the message
            # area, ABOVE the typing box) so chat-element ordering stays correct.
            with progress_ph.container():
                with st.chat_message("user"):
                    st.markdown(conv_query)
                with st.chat_message("assistant"):
                    status_ph = st.empty()
                    thinking_ph = st.empty()
                    stream_ph = st.empty()
                    stream_ph.markdown(
                        '<div class="thinking-dots"><span></span><span></span><span></span></div>',
                        unsafe_allow_html=True,
                    )
        else:
            active_query = pending_query
            if active_query:
                with progress_ph.container():
                    with st.chat_message("assistant"):
                        status_ph = st.empty()
                        thinking_ph = st.empty()
                        stream_ph = st.empty()
                        stream_ph.markdown(
                            '<div class="thinking-dots"><span></span><span></span><span></span></div>',
                            unsafe_allow_html=True,
                        )

        # Context usage line under the typing box.
        if (server_messages or optimistic) and usage_tokens and context_threshold:
            pct = min(100.0, (usage_tokens / context_threshold) * 100.0)
            st.markdown(
                f"""
                <div class="context-usage-bar">
                    <div class="context-usage-track">
                        <div class="context-usage-fill" style="width:{pct:.1f}%"></div>
                    </div>
                    <span class="context-usage-label">Context usage: {usage_tokens} / {context_threshold} tokens</span>
                </div>
                """,
                unsafe_allow_html=True,
            )

    components.html(
        """
        <script>
        const marker = parent.document.querySelector('.chat-scroll-marker');
        if (marker) {
            const block = marker.closest('[data-testid="stVerticalBlock"]');
            const scroller = block ? block.parentElement : null;
            if (scroller) {
                scroller.style.border = 'none';
                scroller.style.padding = '0';
                scroller.style.background = 'transparent';
                scroller.scrollTo({top: scroller.scrollHeight, behavior: 'smooth'});
            }
        }
        </script>
        """,
        height=0,
        width=0,
    )

    active_job_id = st.session_state.get("active_job_id")

    if active_query or (active_job_id and not active_query):
        # Submit a background job or resume an in-flight background job, then
        # block on the SSE stream and render progress live into placeholders.
        _turn_handled = False
        try:
            if active_query:
                job_resp = api_client.post(
                    "/api/v1/chat/stream",
                    json={"query": active_query, "session_id": session_id},
                )
                if job_resp.status_code == 200:
                    data = job_resp.json()
                    job_id = data.get("job_id")
                    if job_id:
                        st.session_state.active_job_id = job_id
                        st.session_state.active_job_session_id = data.get("session_id") or session_id
                        st.session_state.current_session_id = data.get("session_id") or session_id
                        st.session_state.show_wrapper = True
                        if stream_ph is not None:
                            _blocking_stream(job_id, status_ph, thinking_ph, stream_ph)
                        st.session_state.active_job_id = None
                        st.session_state.active_job_session_id = None
                        st.session_state.optimistic_messages = []
                        _turn_handled = True
                    else:
                        # Frozen session or immediate rejection: surface backend message.
                        st.session_state.current_session_id = data.get("session_id") or session_id
                        st.session_state.show_wrapper = True
                        if stream_ph is not None:
                            stream_ph.markdown(data.get("answer") or "Chat unavailable.")
                        st.session_state.optimistic_messages = []
                        _turn_handled = True
                else:
                    st.error(f"Chat request failed: {job_resp.text[:300]}")
                    st.session_state.optimistic_messages = []
            elif active_job_id:
                # Resuming an in-flight background streaming job across reruns/session switches!
                with progress_ph.container():
                    with st.chat_message("assistant"):
                        status_ph = st.empty()
                        thinking_ph = st.empty()
                        stream_ph = st.empty()
                        stream_ph.markdown(
                            '<div class="thinking-dots"><span></span><span></span><span></span></div>',
                            unsafe_allow_html=True,
                        )
                _blocking_stream(active_job_id, status_ph, thinking_ph, stream_ph)
                st.session_state.active_job_id = None
                st.session_state.active_job_session_id = None
                st.session_state.optimistic_messages = []
                _turn_handled = True
        except Exception as e:
            st.error(f"Error during Q&A: {str(e)}")
            st.session_state.optimistic_messages = []
            st.session_state.active_job_id = None

        # Re-run once after a handled turn. The sidebar was rendered BEFORE the
        # session was created (so it missed the new session) and the typing box was
        # rendered DISABLED while the turn's optimistic message was pending. One
        # rerun re-syncs both from server state. Chat-input widget values are cleared
        # first so the same query is never re-submitted.
        if _turn_handled:
            st.session_state.pop("chat_input_conv", None)
            st.session_state.pop("chat_input_landing", None)
            st.rerun()
    return active_query

